fn numeric_evaluator(
    exact: ExactEvaluator,
    representative: &T,
) -> BatchExpressionEvaluator<Complex<T>> {
    exact
        .map_coeff_with_prec(
            &|value| {
                Complex::new(
                    representative.from_rational(&value.re),
                    representative.from_rational(&value.im),
                )
            },
            representative.get_precision(),
        )
        .into_batch_evaluator()
}

